          Records.ComponentMetadataItem.InitializationSql checkIfExists
          Records.ComponentAssetMetadataItem.InitializationSql checkIfExists
          Records.AssetVersionResource.InitializationSql checkIfExists
          Records.AssetVersionMetadataItem.InitializationSql checkIfExists
          Records.AssetType.InitializationSql checkIfExists
          Records.AssetMetadataItem.InitializationSql checkIfExists ]
        |> List.concat

    let run (checkIfExists: bool) (ctx: SqliteContext) =
        sql checkIfExists |> List.iter (ctx.ExecuteSqlNonQuery >> ignore)

    let runInTransaction (checkIfExists: bool) (ctx: SqliteContext) =
        ctx.ExecuteInTransaction(fun t -> sql checkIfExists |> List.iter (t.ExecuteSqlNonQuery >> ignore))
